package com.mannvaasam.config;
import com.mannvaasam.model.*;import com.mannvaasam.repo.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.CommandLineRunner;import org.springframework.context.annotation.*;import org.springframework.security.crypto.password.PasswordEncoder;import java.math.*;
@Configuration public class SeedConfig{@Bean CommandLineRunner seed(UserRepository users,CategoryRepository cats,SellerProfileRepository sellers,ProductRepository products,PasswordEncoder enc,@Value("${app.demo-seller-password:}")String pw,@Value("${app.admin-password:}")String adminPw){return args->{if(!adminPw.isBlank()&&users.findByEmail("admin@mannvaasam.local").isEmpty()){User admin=new User();admin.name="MannVaasam Admin";admin.email="admin@mannvaasam.local";admin.passwordHash=enc.encode(adminPw);admin.role=Role.ADMIN;admin.phone="+91 9000000001";users.save(admin);}if(pw.isBlank()||users.findByEmail("demo.seller@mannvaasam.local").isPresent())return;User u=new User();u.name="MannVaasam Coconut Farm";u.email="demo.seller@mannvaasam.local";u.passwordHash=enc.encode(pw);u.role=Role.SELLER;u.phone="+91 9000000000";users.save(u);SellerProfile s=new SellerProfile();s.user=u;s.businessName="MannVaasam Coconut Farm";s.address="Puducherry, India";s.contact=u.phone;s.latitude=11.9416;s.longitude=79.8083;s.deliveryRadiusKm=100.0;s.deliveryDays=3;s.supportedPincodes="605001,605002";sellers.save(s);String[] names={"Coconut","Tender Coconut","Coconut Oil","Copra","Coconut Milk","Coconut Fiber / Coir","Coconut Saplings","Natural Manure","Farm Tools","Fresh Produce"};for(String n:names){Category c=cats.findByName(n).orElseGet(()->{Category x=new Category();x.name=n;return cats.save(x);});Product p=new Product();p.name="Farm Fresh "+n;p.description="Agriculture product from the MannVaasam demo coconut business.";p.category=c;p.seller=u;p.price=new BigDecimal(n.equals("Coconut Oil")?"240":"35");p.unit=n.equals("Coconut Oil")?"litre":"piece";p.stock=500;p.imageUrl="/images/agriculture-placeholder.svg";products.save(p);}};}}